    // If another thread has already freed the lock, this access is a UAF.
    if (!g_lock) {
        printf("  [Thread %lx] Detected NULL lock on entry.\\n", pthread_self());
        return NULL;
    }

    Inc(&g_waiters);

    // This is the primary site of the use-after-free.
    Enter(&(g_lock->mutex));

    if (!g_done) {
        // Simulate doing some one-time work.
        g_done = 1;
        printf("  [Thread %lx] Performed the one-time action.\\n", pthread_self());
    }

    Exit(&(g_lock->mutex));

    // The last thread out frees the lock.
    if (Dec(&g_waiters) == 0) {
        printf("  [Thread %lx] Last one out, freeing lock %p.\\n", pthread_self(), g_lock);
        // The "free" part of the UAF.
        pthread_mutex_destroy(&g_lock->mutex);
        free(g_lock);
        g_lock = NULL;
    }

    return NULL;
}

