void dst_cache_get_vulnerable(struct dst_cache *cache) {
    printf("      [CACHE] Entering critical section.\\n");

    // 1. Read the current value from the shared cache.
    int current_val = atomic_load(&cache->value);
    printf("      [CACHE] Read value: %d.\\n", current_val);

    // 2. Simulate work/processing time. This is the window where a softirq
    //    could interrupt the execution.
    usleep(1000);

    // --- RACE WINDOW ---
    // Another thread (simulating a softirq) can execute this same function
    // while this thread is sleeping, corrupting the cache.

    // 3. Write a new value back to the cache based on the (now potentially
    //    stale) value that was read earlier.
    atomic_store(&cache->value, current_val + 1);
    printf("      [CACHE] Wrote value: %d.\\n", current_val + 1);

    atomic_fetch_add(&cache->cache_hits, 1);
    printf("      [CACHE] Exiting critical section.\\n");
}

