    printf("  [MIGRATE] Attempting to migrate folio %p.\\n", (void*)f);

    // Wait until the split thread has moved the folio to the local list.
    // This is a synchronization point to ensure the race is possible.
    while (atomic_load(&f->_state) != FOLIO_ON_LOCAL_LIST) {
        usleep(10);
    }
    printf("  [MIGRATE] Folio is on local list, proceeding with migration.\\n");

    // 1. Freeze the reference count. This is the key step that wins the race.
    if (folio_ref_freeze(f)) {
        // 2. If successful, the folio is now "isolated". We can free it.
        printf("  [MIGRATE] Freeing folio %p memory.\\n", (void*)f);
        atomic_store(&f->_state, FOLIO_MIGRATED_AND_FREED);

        // In the real kernel, other cleanup happens. Here, we just free.
        // This is the "free" part of the use-after-free.
        free(f);
    } else {
        printf("  [MIGRATE] Migration failed; could not freeze refs.\\n");
    }
}

